1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	  accumulateUsage,
25	} from './orchestratorHelpers.js';
26	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
27	import {log} from '../shared/logger.js';
28	
29	const DEFAULT_MAX_TOOL_ROUNDS = 5;
30	
31	/** Token counts summed across all provider calls in a single user turn. */
32	export type TurnUsage = UsageMetadata;
33	
34	export interface OrchestratorHooks {
35	  beforeSession?: (session: ChatSession) => Promise<void>;
36	  afterSession?: (session: ChatSession) => Promise<void>;
37	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
38	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
39	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
40	  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: TurnUsage) => Promise<void>;
41	  onError?: (session: ChatSession, error: Error) => Promise<void>;
42	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
43	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
44	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
45	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
46	}
47	
48	export interface ToolBudgetInfo {
49	  maxToolRounds: number;
50	  requestedTools: string[];
51	}
52	
53	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
54	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
55	
56	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
57	
58	export interface ChatOrchestrator {
59	  processMessage(session: ChatSession): Promise<string>;
60	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
61	}
62	
63	export interface ChatOrchestratorOptions {
64	  maxToolRounds?: number;
65	  contextConfig?: Partial<ContextConfig>;
66	  promptBuilderOptions?: PromptBuilderOptions;
67	  hooks?: OrchestratorHooks;
68	  sessionStore?: SessionStore;
69	}
70	
71	interface ToolExecutionResult {
72	  clientMessages: OutgoingMessage[];
73	  suppressOutput: boolean;
74	}
75	export function createChatOrchestrator(
76	  provider: AIProvider,
77	  promptBuilder: PromptBuilder,
78	  toolRegistry?: ToolRegistry,
79	  options?: ChatOrchestratorOptions
80	): ChatOrchestrator {
81	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
82	  const contextConfig = createContextConfig(options?.contextConfig);
83	  const toolInstructions = toolRegistry?.getPromptInstructions();
84	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
85	  const tools = toolRegistry?.getDefinitions();
86	  const hooks = options?.hooks;
87	  const sessionStore = options?.sessionStore;
88	
89	  return {
90	    async processMessage(session: ChatSession): Promise<string> {
91	      return collectText(this.processMessageStream(session));
92	    },
93	
94	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
95	      try {
96	        if (hooks?.beforeSession) await hooks.beforeSession(session);
97	
98	        let userMessage = lastUserContent(session);
99	
100	        if (hooks?.beforeUserInput) {
101	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
102	        }
103	
104	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
105	
106	        const systemPrompt = hooks?.beforeModelResponse
107	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
108	          : baseSystemPrompt;
109	
110	        const messages: Message[] = toMessages(session.entries, contextConfig);
111	        let lastUsage: UsageMetadata | undefined;
112	        let responseText = '';
113	
114	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
115	        for (let round = 0; ; round++) {
116	          log.info('orchestrator', 'starting round', {round});
117	          const pendingToolCalls: ToolCall[] = [];
118	
119	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
120	          responseText += outcome.text;
121	          lastUsage = accumulateUsage(lastUsage, outcome.usage);
122	
123	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
124	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
125	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
126	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
127	            break;
128	          }
129	
130	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
131	          const {clientMessages, suppressOutput} = await executeToolCalls(
132	            pendingToolCalls,
133	            messages,
134	            session,
135	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
136	          );
137	          log.info('orchestrator', 'tool execution complete', {
138	            clientMessageCount: clientMessages.length,
139	            clientMessageTypes: clientMessages.map(m => m.type),
140	            suppressOutput,
141	          });
142	
143	          if (clientMessages.length > 0) {
144	            yield {type: 'tool_result' as const, clientMessages};
145	          }
146	
147	          if (suppressOutput) {
148	            yield {type: 'suppress_output' as const};
149	          }
150	        }
151	
152	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
153	      } catch (error) {
154	        if (hooks?.onError && error instanceof Error) {
155	          await hooks.onError(session, error);
156	        }
157	        throw error;
158	      } finally {
159	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
160	        commitStreamingEntries(session);
161	        try {
162	          if (hooks?.afterSession) await hooks.afterSession(session);
163	        } finally {
164	          await saveSession(sessionStore, session);
165	        }
166	      }
167	    },
168	  };
169	}
170	
171	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
172	function normalizeToolRounds(value: number | undefined): number {
173	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
174	  return Math.max(0, Math.floor(value));
175	}
176	
177	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
178	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
179	  if (round < maxToolRounds) return false;
180	  log.warn('orchestrator', 'tool budget exhausted', {
181	    maxToolRounds,
182	    requestedTools: pendingToolCalls.map(tc => tc.name),
183	  });
184	  return true;
185	}
186	
187	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
188	async function* closeExhaustedTurn(
189	  session: ChatSession,
190	  budget: ToolBudgetInfo,
191	  hook?: OnToolBudgetExhausted
192	): AsyncGenerator<MessageChunk, string> {
193	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
194	  if (sentence !== '') yield {type: 'text', text: sentence};
195	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
196	  return sentence;
197	}
198	
199	interface RoundOutcome {
200	  stopReason: string;
201	  text: string;
202	  usage?: UsageMetadata;
203	}
204	
205	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
206	async function* streamRound(
207	  provider: AIProvider,
208	  request: SendMessageParams,
209	  pendingToolCalls: ToolCall[]
210	): AsyncGenerator<MessageChunk, RoundOutcome> {
211	  let stopReason = '';
212	  let text = '';
213	  let usage: UsageMetadata | undefined;
214	
215	  for await (const chunk of provider.sendMessage(request)) {
216	    yield chunk;
217	    collectToolCalls(chunk, pendingToolCalls);
218	    stopReason = extractStopReason(chunk) ?? stopReason;
219	    usage = extractUsage(chunk) ?? usage;
220	    if (chunk.type === 'text') text += chunk.text;
221	  }
222	
223	  return {stopReason, text, usage};
224	}
225	
226	// A changed message is also written back to the session's last user entry.
227	async function rewriteUserMessage(
228	  session: ChatSession,
229	  userMessage: string,
230	  hook: (session: ChatSession, userMessage: string) => Promise<string>
231	): Promise<string> {
232	  const modified = await hook(session, userMessage);
233	  if (modified === userMessage) return userMessage;
234	
235	  updateLastUserContent(session, modified);
236	  return modified;
237	}
238	
239	function lastUserContent(session: ChatSession): string {
240	  for (let i = session.entries.length - 1; i >= 0; i--) {
241	    const entry = session.entries[i];
242	    if (entry.role === 'user') return entry.content;
243	  }
244	  return '';
245	}
246	
247	function updateLastUserContent(session: ChatSession, content: string): void {
248	  for (let i = session.entries.length - 1; i >= 0; i--) {
249	    const entry = session.entries[i];
250	    if (entry.role === 'user') {
251	      entry.content = content;
252	      return;
253	    }
254	  }
255	}
256	
257	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
258	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
259	  const context: ToolContext = {
260	    userId: session.userId,
261	    sessionId: session.sessionId,
262	    workspaceId: session.workspaceId,
263	    authHeaders: session.authHeaders,
264	  };
265	
266	  return async (tc: ToolCall): Promise<ToolResponse> => {
267	    const declined =
268	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
269	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
270	  };
271	}
272	
273	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
274	async function consultPolicy(
275	  policy: BeforeToolCall,
276	  session: ChatSession,
277	  tc: ToolCall
278	): Promise<ToolResponse | undefined> {
279	  try {
280	    return await policy(session, tc);
281	  } catch (error) {
282	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
283	      tool: tc.name,
284	      errorType: error instanceof Error ? error.name : typeof error,
285	    });
286	    return {result: `The ${tc.name} call was declined and not performed.`};
287	  }
288	}
289	
290	async function executeToolCalls(
291	  pendingToolCalls: ToolCall[],
292	  messages: Message[],
293	  session: ChatSession,
294	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
295	): Promise<ToolExecutionResult> {
296	  messages.push(buildToolCallMessages(pendingToolCalls));
297	
298	  const responses = await Promise.all(
299	    pendingToolCalls.map(async tc => {
300	      const response = await runToolCall(tc);
301	      return {tc, response};
302	    })
303	  );
304	
305	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
306	    type: 'tool_result' as const,
307	    toolUseId: tc.id,
308	    content: response.result,
309	  }));
310	  messages.push({role: 'user', content: toolResults});
311	
312	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
313	
